<?php
require __DIR__.'/_layout.php';if(instructor_user()){header('Location:index.php');exit;}$err='';$success='';$username='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();try{if(recovery_locked('instructor'))throw new RuntimeException('Muitas tentativas incorretas. Aguarde 15 minutos e tente novamente.');$name=trim((string)($_POST['full_name']??''));$birth=trim((string)($_POST['birth_date']??''));$cpf=normalize_cpf((string)($_POST['cpf']??''));$pass=(string)($_POST['password']??'');$pass2=(string)($_POST['password2']??'');if($name===''||$birth===''||!cpf_valid($cpf))throw new RuntimeException('Não foi possível confirmar os dados informados.');if(strlen($pass)<10)throw new RuntimeException('A nova senha deve ter pelo menos 10 caracteres.');if($pass!==$pass2)throw new RuntimeException('As novas senhas não coincidem.');$st=db()->prepare("SELECT * FROM instructors WHERE birth_date=? AND cpf=? AND active=1");$st->execute([$birth,$cpf]);$found=null;foreach($st->fetchAll() as $candidate){if(recovery_normalize_name((string)$candidate['full_name'])===recovery_normalize_name($name)){$found=$candidate;break;}}if(!$found){recovery_register_failure('instructor');throw new RuntimeException('Não foi possível confirmar os dados informados.');}db()->prepare("UPDATE instructors SET password_hash=?,updated_at=? WHERE id=?")->execute([password_hash($pass,PASSWORD_DEFAULT),now_iso(),(int)$found['id']]);recovery_clear('instructor');$username=(string)$found['username'];$success='Senha redefinida com sucesso.';}catch(Throwable $e){$err=$e->getMessage();}}
instructor_header('Esqueci minha senha');$logo='../'.ltrim(setting('logo_path','assets/brasao_bamab_2026.png'),'/');?>
<div class="instructor-login-card bamab-instructor-login recovery-card"><img class="instructor-login-crest" src="<?=e($logo)?>" alt="Brasão oficial BAMAB"><div class="internal-badge">RECUPERAÇÃO DE ACESSO</div><div class="instructor-login-greeting"><span><?=e(bamab_greeting())?>!</span><h2>Redefinir senha</h2><p>Use o nome completo, data de nascimento e CPF cadastrados pelo Admin.</p></div><?php if($success):?><div class="alert ok"><?=e($success)?><?php if($username):?><br>Seu login é: <strong><?=e($username)?></strong><?php endif;?></div><a class="instr-primary forgot-success-button" href="login.php?reset=1">VOLTAR PARA O LOGIN</a><?php else:?><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Nome completo<input name="full_name" required autocomplete="name"></label><label>Data de nascimento<input type="date" name="birth_date" required></label><label>CPF<input name="cpf" inputmode="numeric" required></label><label>Nova senha<input type="password" name="password" minlength="10" required autocomplete="new-password"></label><label>Confirmar nova senha<input type="password" name="password2" minlength="10" required autocomplete="new-password"></label><button class="primary">REDEFINIR MINHA SENHA</button></form><?php endif;?><a class="instr-secondary instructor-back-site" href="login.php">← VOLTAR AO LOGIN</a></div><?php instructor_footer();?>
